//! The plane's keypair + PKCS#10 CSR, generated by `maknae_crypto::csr::generate_csr` with the
//! configured `PlaneKey`, an EMPTY subject and exactly one URI SAN, then self-checked. The
//! private key is returned as `Zeroizing<Vec<u8>>` (wiped on drop) and never leaves memory.
//!
//! ## Why this file is ADR-0016 **T3** (not T1), and why that is not a coverage dodge
//!
//! The security *decision* for a plane CSR — "empty subject, exactly one URI-SAN,
//! the configured key algorithm" — is NOT in this file. It lives in the pure predicates of `csr.rs`
//! (`csr_matches_plane_shape` + its parts), which are **T1**: mutation-covered and
//! ≥95% region, with negative tests that prove they REJECT a bad shape. This file
//! only *orchestrates I/O*: it calls `maknae_crypto::csr::generate_csr` (a non-deterministic
//! keygen) and propagates its failures via `?`. That arm cannot be
//! unit-covered without forcing keygen to fail on valid input — that would test
//! rcgen's error handling, not our logic. That is the definition of a T3 boundary
//! (I/O + external-error plumbing). No decision logic was demoted: the shape
//! decision is T1 and self-checked below, fail-closed.
use crate::csr::csr_matches_plane_shape;
use crate::{Plane, VaultError};
use maknae_crypto::plane_key::PlaneKey;
use zeroize::Zeroizing;

/// Generate the plane's keypair + CSR. Returns `(key_der, csr_pem)`.
pub fn generate_plane_csr(
    plane: Plane,
    deployment_id: &str,
    plane_key: PlaneKey,
) -> Result<(Zeroizing<Vec<u8>>, String), VaultError> {
    let want = plane.uri_san(deployment_id);
    let params = maknae_crypto::csr::CsrParams {
        uris: vec![want.clone()],
        ..Default::default()
    };
    let (key, csr_pem) = maknae_crypto::csr::generate_csr(plane_key.into(), &params)?;
    // Fail-closed self-check via the T1 shape predicate (never hand Vault a CSR whose
    // shape we did not intend). The reject path is proven by csr.rs's negative tests.
    if !csr_matches_plane_shape(&csr_pem, &want, plane_key) {
        return Err(VaultError::CsrGen(
            "generated CSR failed its shape self-check (subject/SAN/key algorithm)".to_string(),
        ));
    }
    Ok((Zeroizing::new(key.pkcs8_der().to_vec()), csr_pem))
}

#[cfg(test)]
mod tests {
    use super::*;
    use maknae_crypto::rustls::pki_types::PrivateKeyDer;

    #[test]
    fn each_plane_key_generates_its_own_shape_and_a_key_rustls_signs_with() {
        let schemes = PlaneKey::ALL.map(PlaneKey::signature_scheme);
        for k in PlaneKey::ALL {
            let (key_der, csr_pem) = generate_plane_csr(Plane::Kernel, "dev-01", k).unwrap();
            assert!(csr_matches_plane_shape(
                &csr_pem,
                "maknae://dev-01/plane/kernel",
                k
            ));
            let signing = maknae_crypto::tls::load_private_key(
                &maknae_crypto::policy().unwrap().tls,
                PrivateKeyDer::Pkcs8(key_der.to_vec().into()),
            )
            .unwrap();
            for scheme in schemes {
                let chosen = signing.choose_scheme(&[scheme]).map(|s| s.scheme());
                if scheme == k.signature_scheme() {
                    assert_eq!(chosen, Some(scheme), "{k:?}");
                } else {
                    assert_eq!(chosen, None, "{k:?} offered {scheme:?}");
                }
            }
        }
    }

    #[test]
    fn a_plane_csr_carries_no_usage_extensions() {
        use x509_parser::prelude::FromDer;
        for k in PlaneKey::ALL {
            let (_, pem) = generate_plane_csr(Plane::Kernel, "dev-01", k).unwrap();
            let (_, der) = x509_parser::pem::parse_x509_pem(pem.as_bytes()).unwrap();
            let (_, csr) = x509_parser::certification_request::X509CertificationRequest::from_der(
                &der.contents,
            )
            .unwrap();
            let exts: Vec<_> = csr.requested_extensions().into_iter().flatten().collect();
            assert!(
                exts.iter().all(|e| matches!(
                    e,
                    x509_parser::extensions::ParsedExtension::SubjectAlternativeName(_)
                )),
                "{k:?}: {exts:?}"
            );
            assert_eq!(exts.len(), 1, "{k:?}");
        }
    }
}
